<script setup>
import {ref,computed,onUnmounted} from 'vue';import BaseModal from '../components/BaseModal.vue';import {state,company,api,scope,useResource,notify,changed,ask} from '../lib/workspace';import {amount,inputMoney,money,uid} from '../lib/format';
const tax=ref('icms'),show=ref(false),mode=ref('assessment'),form=ref({}),context=ref({}),error=ref(''),busy=ref(false),detail=ref(null);let baseline='';
const {data,error:loadError}=useResource(async()=>{if(!state.companyId)return {documents:[],rules:[],assessments:[],adjustments:[]};const [documents,rules,assessments,adjustments]=await Promise.all([api(scope(`/documents?period=${state.period}`)),api(scope('/rules')),api(scope(`/assessments?period=${state.period}`)),api(scope(`/tax-adjustments?period=${state.period}`))]);return {documents,rules,assessments,adjustments};},{documents:[],rules:[],assessments:[],adjustments:[]});
const rules=computed(()=>data.value.rules.filter(r=>r.tax.toLowerCase()===tax.value&&r.status==='validated'&&r.active&&!r.superseded_by));
function open(type='assessment'){mode.value=type;context.value={id:state.companyId,name:company.value.name,period:state.period};form.value={tax:tax.value,period:state.period,idempotency_key:uid(),opening_credit:'0,00',source:'',responsible:'',entries:[],kind:'debit',amount:'',reason:''};baseline=JSON.stringify(form.value);show.value=true;error.value='';state.editor={name:'Pré-apuração',companyId:state.companyId};}
async function close(){if(busy.value)return;if(baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar edição?',message:'A memória ainda não foi registrada.',confirmLabel:'Descartar'}))return;show.value=false;state.editor=null;}
async function save(){busy.value=true;error.value='';try{const p={...form.value,opening_credit:amount(form.value.opening_credit),amount:amount(form.value.amount),entries:form.value.entries.map(e=>({...e,base:amount(e.base)}))};const r=await api(scope(mode.value==='assessment'?'/assessments':'/tax-adjustments',context.value.id),{method:'POST',body:p});show.value=false;state.editor=null;changed();if(r.snapshot)detail.value=r;notify('Registro fiscal salvo com memória de cálculo.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function reverse(a){const reason=await ask({title:'Estornar ajuste fiscal',message:'O ajuste será preservado no histórico e deixará de compor as próximas memórias.',inputLabel:'Justificativa',required:true,confirmLabel:'Estornar ajuste'});if(!reason)return;try{await api(scope(`/tax-adjustments/${a.id}/reverse`),{method:'POST',body:{reason,period:state.period}});changed();}catch(e){notify(e.message,'error');}}
onUnmounted(()=>{if(show.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">CONFERÊNCIA TRIBUTÁRIA</div><h1>Pré-apuração fiscal</h1><p>Regras revisadas, bases explícitas e memória por tributo.</p></div><div class="actions"><button class="button outline" @click="open('adjustment')">Novo ajuste</button><button class="button primary" @click="open()">Nova memória</button></div></header><p class="message warning">A incidência, a composição da base e a admissibilidade do crédito dependem de revisão fiscal. Não há compensação entre tributos nem transmissão de obrigações.</p><p v-if="loadError" class="message error">{{loadError}}</p><select v-model="tax" aria-label="Tributo da pré-apuração"><option v-for="t in ['icms','ipi','iss','pis','cofins','ibs','cbs']" :key="t" :value="t">{{t.toUpperCase()}}</option></select><section class="panel"><div class="table-scroll"><table><thead><tr><th>Memória</th><th>Tributo</th><th>Débitos</th><th>Créditos</th><th>A recolher</th><th>Crédito a transportar</th><th>Conferência</th><th></th></tr></thead><tbody><tr v-for="a in data.assessments.filter(a=>a.tax===tax)" :key="a.id"><td>#{{a.id}} · {{a.created_at}}</td><td>{{a.tax.toUpperCase()}}</td><td>{{money(a.snapshot.debit_cents)}}</td><td>{{money(a.snapshot.credit_cents)}}</td><td>{{money(a.snapshot.payable_cents)}}</td><td>{{money(a.snapshot.carry_credit_cents)}}</td><td><span class="badge" :class="a.stale?'warning':'success'">{{a.stale?'Origem alterada — refazer':'Origem preservada'}}</span></td><td><button class="button small" @click="detail=a">Ver memória</button></td></tr></tbody></table></div></section><h2>Ajustes da competência</h2><section class="panel"><table><thead><tr><th>Tributo</th><th>Natureza</th><th>Valor</th><th>Motivo / fonte</th><th></th></tr></thead><tbody><tr v-for="a in data.adjustments.filter(a=>a.tax===tax)" :key="a.id"><td>{{a.tax.toUpperCase()}}</td><td>{{a.kind==='debit'?'Débito':'Crédito'}}</td><td>{{money(a.amount_cents)}}</td><td>{{a.reason}} · {{a.source}}</td><td><span v-if="a.reversed_at">Estornado</span><button v-else class="button small" @click="reverse(a)">Estornar</button></td></tr></tbody></table></section>
<BaseModal v-if="show" :title="mode==='assessment'?'Nova memória de pré-apuração':'Novo ajuste fiscal'" :subtitle="`${context.name} · ${context.period} · ${tax.toUpperCase()}`" wide @close="close"><p v-if="error" class="message error" role="alert">{{error}}</p><form id="assessment-form" @submit.prevent="save"><div class="form-grid"><label class="span-2">Fundamentação / fonte normativa *<textarea v-model="form.source" required/></label><template v-if="mode==='assessment'"><label>Responsável pela conferência *<input v-model="form.responsible" required/></label><label>Saldo credor anterior deste tributo<input v-model="form.opening_credit" inputmode="decimal"/></label></template><template v-else><label>Natureza<select v-model="form.kind"><option value="debit">Débito</option><option value="credit">Crédito</option></select></label><label>Valor (R$) *<input v-model="form.amount" required/></label><label class="span-2">Justificativa *<input v-model="form.reason" required/></label></template></div><template v-if="mode==='assessment'"><p v-if="!rules.length" class="message warning">Cadastre e revise uma regra deste tributo em Parâmetros antes de apurar.</p><div v-for="(e,i) in form.entries" :key="i" class="assessment-entry form-grid three"><label>Documento escriturado<select v-model.number="e.document_id" required @change="e.base=inputMoney(data.documents.find(d=>d.id===e.document_id)?.total_cents)"><option value="">Selecione</option><option v-for="d in data.documents.filter(d=>d.status==='booked')" :key="d.id" :value="d.id">{{d.number}} · {{d.partner_name}}</option></select></label><label>Regra revisada<select v-model.number="e.rule_id" required><option value="">Selecione</option><option v-for="r in rules" :key="r.id" :value="r.id">{{r.name}} · {{r.rate}}% · {{r.source}}</option></select></label><label>Natureza<select v-model="e.effect"><option value="debit">Débito</option><option value="credit">Crédito conferido</option></select></label><label>Base conferida (R$)<input v-model="e.base" required/></label><label class="span-2">Fundamento da base / direito ao crédito<input v-model="e.reason" required/></label><button type="button" class="text-button" @click="form.entries.splice(i,1)">Remover base</button></div><button type="button" class="button outline" @click="form.entries.push({document_id:'',rule_id:'',effect:'debit',base:'',reason:''})">Adicionar base conferida</button></template></form><template #footer><button class="button" @click="close" :disabled="busy">Cancelar</button><button class="button primary" form="assessment-form" :disabled="busy">Registrar {{mode==='assessment'?'memória':'ajuste'}}</button></template></BaseModal>
<BaseModal v-if="detail" title="Memória de cálculo" wide @close="detail=null"><p>{{detail.source}} · Conferência: {{detail.responsible}}</p><p>{{detail.snapshot.scope_note}}</p><p>Saldo anterior: {{money(detail.snapshot.opening_credit_cents)}} · a recolher: {{money(detail.snapshot.payable_cents)}} · a transportar: {{money(detail.snapshot.carry_credit_cents)}}</p><div class="table-scroll"><table><thead><tr><th>Documento / versão</th><th>Regra / versão</th><th>Base</th><th>Alíquota</th><th>Resultado</th><th>Natureza</th><th>Fundamento</th></tr></thead><tbody><tr v-for="(e,i) in detail.snapshot.entries" :key="i"><td>{{e.document_number}} · v{{e.document_version}}</td><td>#{{e.rule_id}} · v{{e.rule_version}}</td><td>{{money(e.base_cents)}}</td><td>{{e.rate}}%</td><td>{{money(e.result_cents)}}</td><td>{{e.effect==='debit'?'Débito':'Crédito'}}</td><td>{{e.reason}} · {{e.source}}</td></tr></tbody></table></div><p>Arredondamento: metade para cima, em centavos, por base conferida.</p><small class="wrap-anywhere">Identificador da memória: {{detail.fingerprint}}</small><template #footer><button class="button" @click="detail=null">Fechar</button></template></BaseModal></div></template>
